1	// Regression coverage for subject identifiers compared by their exact
2	// submitted bytes. The platform accepts subject identifiers that carry
3	// bytes which are not valid UTF-8; two identifiers that render identically
4	// may still be different subjects. Authorization must never merge them via
5	// a character replacement, and audit queries must never treat them as one
6	// subject.
7	//
8	// Three enabled subjects in one organization read one resource; the
9	// organization, action and legal scope are identical, and the subject
10	// identifiers differ at exactly one middle position:
11	//
12	//   - a lone 0xFF byte,
13	//   - a lone 0xFE byte,
14	//   - a genuine U+FFFD code point (valid UTF-8, three bytes EF BF BD).
15	//
16	// The one published version carries an allow policy for the first subject
17	// and an explicit deny policy for the second; the third has no policy at
18	// all. The decisions must come out as allow, own-policy deny and
19	// no-authorization default deny respectively, each explained by its own
20	// policy evidence at the published version, and the audit chain plus
21	// subject-filtered paging must keep the three identities apart byte for
22	// byte. The empty-value edge keeps its legacy meaning too: a request
23	// without a subject identifier is an envelope denial at version 0 with no
24	// matched policy, while an empty subject filter in an audit query means
25	// "do not filter by subject" rather than "query the missing identifier".
26	package darksafe
27	
28	import (
29		"bytes"
30		"encoding/json"
31		"reflect"
32		"testing"
33	)
34	
35	// rawByteSubjects returns the three byte-different-but-display-conflated
36	// subject identifiers used by this file. The surrounding content is
37	// identical; exactly one middle position differs.
38	func rawByteSubjects() (withFF, withFE, withReplacement string) {
39		return "svc-" + invalidByte + "-reader",
40			"svc-" + anotherInvalidByte + "-reader",
41			"svc-" + replacementRune + "-reader"
42	}
43	
44	// TestRawByteSubjectIdentifiersStayDistinctInDecisions pins the
45	// authorization contract: matching is against the request's raw subject
46	// bytes, so a replacement of 0xFF with 0xFE (or with a genuine U+FFFD) can
47	// never make one subject ride another subject's allow or deny.
48	func TestRawByteSubjectIdentifiersStayDistinctInDecisions(t *testing.T) {
49		subFF, subFE, subFD := rawByteSubjects()
50	
51		// Document the premise this regression guards: Go string comparison
52		// distinguishes the three identifiers, while encoding/json renders the
53		// two lone invalid bytes identically. Any normalization at the
54		// authorization boundary would collapse the first two.
55		if subFF == subFE || subFF == subFD || subFE == subFD {
56			t.Fatalf("test premise broken: identifiers must differ pairwise: %q %q %q", subFF, subFE, subFD)
57		}
58		jFF, _ := json.Marshal(subFF)
59		jFE, _ := json.Marshal(subFE)
60		if !bytes.Equal(jFF, jFE) {
61			t.Fatalf("test premise broken: JSON renders the invalid bytes differently: %s vs %s", jFF, jFE)
62		}
63	
64		const (
65			org        = "acme"
66			resourceID = "ledger-2026"
67			scope      = "acme/factory/ledger"
68			action     = "read"
69		)
70		s := NewStore()
71		version, err := s.Publish(org, 0, []Policy{
72			{ID: "p-ledger-read-ff", Subject: subFF, Action: action, Scope: scope, Effect: EffectAllow},
73			{ID: "p-ledger-read-fe-deny", Subject: subFE, Action: action, Scope: scope, Effect: EffectDeny},
74			// No policy at all for the genuine-U+FFFD subject.
75		})
76		if err != nil || version != 1 {
77			t.Fatalf("publish = %d, %v; want version 1", version, err)
78		}
79	
80		readReq := func(subject string) OrgRequest {
81			return OrgRequest{
82				SubjectOrg:  org,
83				ResourceOrg: org,
84				Subject:     Subject{ID: subject, Kind: "service"}, // all enabled
85				Resource:    Resource{ID: resourceID, Scope: scope},
86				Action:      action,
87			}
88		}
89	
90		// Subject 1: its own allow policy matches; the match list carries only
91		// that policy, at the version actually published.
92		allowFF := s.Decide(org, readReq(subFF))
93		if !allowFF.Allowed {
94			t.Fatalf("0xFF subject decision = %+v, want allowed", allowFF)
95		}
96		if allowFF.Reason != "matched allow policy" {
97			t.Fatalf("0xFF subject reason = %q, want %q", allowFF.Reason, "matched allow policy")
98		}
99		if want := []string{"p-ledger-read-ff"}; !reflect.DeepEqual(allowFF.Matched, want) {
100			t.Fatalf("0xFF subject matched = %q, want %q", allowFF.Matched, want)
101		}
102		if allowFF.Version != 1 {
103			t.Fatalf("0xFF subject version = %d, want the published version 1", allowFF.Version)
104		}
105	
106		// Subject 2: denied by ITS OWN deny policy. The first subject's allow
107		// must not travel with it, and the explanation is the policy-deny
108		// reason rather than the default denial.
109		denyFE := s.Decide(org, readReq(subFE))
110		if denyFE.Allowed {
111			t.Fatalf("0xFE subject decision = %+v, want denied by its deny policy", denyFE)
112		}
113		if denyFE.Reason != "matched deny policy" {
114			t.Fatalf("0xFE subject reason = %q, want %q", denyFE.Reason, "matched deny policy")
115		}
116		if want := []string{"p-ledger-read-fe-deny"}; !reflect.DeepEqual(denyFE.Matched, want) {
117			t.Fatalf("0xFE subject matched = %q, want only its own deny %q (no other subject's policy)", denyFE.Matched, want)
118		}
119		if denyFE.Version != 1 {
120			t.Fatalf("0xFE subject version = %d, want the published version 1", denyFE.Version)
121		}
122	
123		// Subject 3: no policy names it, so the default denial applies with an
124		// empty match list. Neither the allow nor the deny of the
125		// look-alike subjects may be used as its basis.
126		noPolicyFD := s.Decide(org, readReq(subFD))
127		if noPolicyFD.Allowed {
128			t.Fatalf("U+FFFD subject decision = %+v, want default deny (no matching allow)", noPolicyFD)
129		}
130		if noPolicyFD.Reason != "no matching allow policy" {
131			t.Fatalf("U+FFFD subject reason = %q, want %q", noPolicyFD.Reason, "no matching allow policy")
132		}
133		if len(noPolicyFD.Matched) != 0 {
134			t.Fatalf("U+FFFD subject matched = %q, want no matched policy", noPolicyFD.Matched)
135		}
136		if noPolicyFD.Version != 1 {
137			t.Fatalf("U+FFFD subject version = %d, want the published version 1 it was evaluated under", noPolicyFD.Version)
138		}
139	
140		// The three explanations are pairwise distinguishable: an allow, a
141		// policy-driven deny, and a no-authorization default deny.
142		reasons := []string{allowFF.Reason, denyFE.Reason, noPolicyFD.Reason}
143		for i := 0; i < len(reasons); i++ {
144			for j := i + 1; j < len(reasons); j++ {
145				if reasons[i] == reasons[j] {
146					t.Fatalf("decisions %d and %d share reason %q; the three outcomes must be distinguishable", i, j, reasons[i])
147				}
148			}
149		}
150	}
151	
152	// TestRawByteSubjectAuditKeepsIdentitiesAndDecisionsApart builds a chain
153	// in which the three subjects' decisions are interleaved with another
154	// subject's decisions. Every decision record must preserve the submitted
155	// subject bytes and the returned decision, and a subject-filtered, paged
156	// query for any one non-empty identifier must return only records whose
157	// subject is byte-identical — no look-alike mixing in, no record missing,
158	// no record repeated, even across pages. The third subject's default
159	// denials are real audit records and must be found exactly like any
160	// allowed decision.
161	func TestRawByteSubjectAuditKeepsIdentitiesAndDecisionsApart(t *testing.T) {
162		subFF, subFE, subFD := rawByteSubjects()
163	
164		const (
165			org        = "acme"
166			other      = "svc-billing-reader"
167			resourceID = "ledger-2026"
168			scope      = "acme/factory/ledger"
169			action     = "read"
170		)
171		s := NewStore()
172		if _, err := s.Publish(org, 0, []Policy{
173			{ID: "p-ledger-read-ff", Subject: subFF, Action: action, Scope: scope, Effect: EffectAllow},
174			{ID: "p-ledger-read-fe-deny", Subject: subFE, Action: action, Scope: scope, Effect: EffectDeny},
175		}); err != nil {
176			t.Fatal(err)
177		}
178	
179		readReq := func(subject string) OrgRequest {
180			return OrgRequest{
181				SubjectOrg:  org,
182				ResourceOrg: org,
183				Subject:     Subject{ID: subject, Kind: "service"},
184				Resource:    Resource{ID: resourceID, Scope: scope},
185				Action:      action,
186			}
187		}
188	
189		// Chain layout (seq 1 is the publish):
190		//	seq 2  subFF allow      seq 3  other (default deny)
191		//	seq 4  subFE deny       seq 5  other (default deny)
192		//	seq 6  subFD default    seq 7  other (default deny)
193		//	seq 8  subFF allow      seq 9  other (default deny)
194		//	seq 10 subFE deny       seq 11 other (default deny)
195		//	seq 12 subFD default
196		decide := func(subject string) Decision {
197			return s.Decide(org, readReq(subject))
198		}
199		firstFF := decide(subFF)  // 2
200		decide(other)             // 3
201		firstFE := decide(subFE)  // 4
202		decide(other)             // 5
203		firstFD := decide(subFD)  // 6
204		decide(other)             // 7
205		secondFF := decide(subFF) // 8
206		decide(other)             // 9
207		secondFE := decide(subFE) // 10
208		decide(other)             // 11
209		secondFD := decide(subFD) // 12
210	
211		// The complete export preserves each request's full subject bytes and
212		// the decision actually returned, and the raw-byte records verify.
213		recs, cp, err := s.AuditExport(org, 0)
214		if err != nil {
215			t.Fatal(err)
216		}
217		if err := VerifyAudit(org, recs, cp); err != nil {
218			t.Fatalf("chain with raw-byte subjects must verify: %v", err)
219		}
220		if len(recs) != 12 {
221			t.Fatalf("exported %d records, want 12", len(recs))
222		}
223		wantAtSeq := map[int]struct {
224			subject  string
225			decision Decision
226		}{
227			2: {subFF, firstFF}, 4: {subFE, firstFE}, 6: {subFD, firstFD},
228			8: {subFF, secondFF}, 10: {subFE, secondFE}, 12: {subFD, secondFD},
229		}
230		for seq, want := range wantAtSeq {
231			got := recs[seq-1].Decision
232			if got == nil {
233				t.Fatalf("seq %d has no decision payload", seq)
234			}
235			if got.Request.Subject.ID != want.subject {
236				t.Fatalf("seq %d stored subject %q, want byte-exact %q", seq, got.Request.Subject.ID, want.subject)
237			}
238			if !reflect.DeepEqual(got.Decision, want.decision) {
239				t.Fatalf("seq %d stored decision %+v, want returned %+v", seq, got.Decision, want.decision)
240			}
241		}
242	
243		// Subject-filtered walks, one matching record per page so every match
244		// boundary is genuinely crossed. The helper also rejects cursor
245		// repetition (non-termination) and checkpoint drift.
246		cases := []struct {
247			name     string
248			subject  string
249			wantSeqs []int
250			allowed  bool
251			reason   string
252			matched  []string
253		}{
254			{"0xFF subject", subFF, []int{2, 8}, true, "matched allow policy", []string{"p-ledger-read-ff"}},
255			{"0xFE subject", subFE, []int{4, 10}, false, "matched deny policy", []string{"p-ledger-read-fe-deny"}},
256			// The third subject's default denials are audited and findable even
257			// though no policy ever matched.
258			{"U+FFFD subject", subFD, []int{6, 12}, false, "no matching allow policy", []string{}},
259		}
260		for _, tc := range cases {
261			t.Run(tc.name, func(t *testing.T) {
262				got, _ := subjectPageWalk(t, s, org, 1, 1, "", tc.subject)
263				if seqs := recordSeqs(got); !reflect.DeepEqual(seqs, tc.wantSeqs) {
264					t.Fatalf("seqs = %v, want %v; look-alike records mixed in, dropped or repeated", seqs, tc.wantSeqs)
265				}
