267				for _, r := range got {
268					// Byte-identical subject, including the raw invalid bytes.
269					if r.Decision.Request.Subject.ID != tc.subject {
270						t.Fatalf("seq %d subject %q, want %q", r.Seq, r.Decision.Request.Subject.ID, tc.subject)
271					}
272					if r.Decision.Decision.Allowed != tc.allowed ||
273						r.Decision.Decision.Reason != tc.reason ||
274						!reflect.DeepEqual(r.Decision.Decision.Matched, tc.matched) ||
275						r.Decision.Decision.Version != 1 {
276						t.Fatalf("seq %d preserved decision = %+v, want allowed=%v reason=%q matched=%q version=1",
277							r.Seq, r.Decision.Decision, tc.allowed, tc.reason, tc.matched)
278					}
279				}
280			})
281		}
