364		// subject's decisions, including u1's and the missing-identifier one.
365		// It must not be reinterpreted as a filter for the missing identifier.
366		allDecisions := drainAudit(t, s, org, AuditDecision, "")
367		if len(allDecisions) != 2 {
368			t.Fatalf("decision-only unfiltered query returned %d records, want 2", len(allDecisions))
369		}
370		var sawNonEmpty, sawEmpty bool
371		for _, r := range allDecisions {
372			if r.Decision.Request.Subject.ID == "" {
373				sawEmpty = true
374			} else {
375				sawNonEmpty = true
376			}
377		}
378		if !sawNonEmpty {
379			t.Fatal("empty subject filter behaved like a missing-identifier filter: u1's decision was dropped")
380		}
381		if !sawEmpty {
382			t.Fatal("the missing-subject decision was not returned by the unfiltered query")
383		}
384	
385		// With no category either, policy-change records come back as well, so
386		// the empty filter is the full history, not a subject-shaped subset.
387		full := drainAudit(t, s, org, "", "")
388		if len(full) != 3 || full[0].Kind != AuditPolicyChange {
389			t.Fatalf("unfiltered query = %d records, want publish + 2 decisions", len(full))
390		}
391	}
