1	package darksafe
2	
3	import (
4		"errors"
5		"reflect"
6		"testing"
7	)
8	
9	// syntheticRecord fingerprints one record exactly as the store would,
10	// letting tests build chains that can never occur through the live API
11	// (e.g. a decision naming a version published later).
12	func syntheticRecord(org string, seq int, kind string, change *PolicyChange, decision *DecisionRecord, prev string) AuditRecord {
13		r := AuditRecord{
14			Org:             org,
15			Seq:             seq,
16			Kind:            kind,
17			Change:          change,
18			Decision:        decision,
19			PrevFingerprint: prev,
20		}
21		r.Fingerprint = fingerprintFor(&r)
22		return r
23	}
24	
25	// syntheticChain assumes a gapless, correctly fingerprinted chain.
26	func syntheticChain(org string, payloads []func(seq int) (string, *PolicyChange, *DecisionRecord)) ([]AuditRecord, Checkpoint) {
27		recs := make([]AuditRecord, 0, len(payloads))
28		prev := genesisFingerprint(org)
29		for i, build := range payloads {
30			seq := i + 1
31			kind, change, decision := build(seq)
32			r := syntheticRecord(org, seq, kind, change, decision, prev)
33			recs = append(recs, r)
34			prev = r.Fingerprint
35		}
36		return recs, Checkpoint{Org: org, EndSeq: len(recs), Fingerprint: prev}
37	}
38	
39	func TestOfflineReviewReplaysRecordedVersion(t *testing.T) {
40		s := NewStore()
41		v1, _ := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
42		req := request("acme", "u1", "r1", "org/a", "read")
43		original := s.Decide("acme", req) // seq 2, version 1, allowed
44		origDeny := s.Decide("acme", request("acme", "u2", "r1", "org/a", "read"))
45	
46		// Later publishes and a rollback happen after the export material.
47		s.Publish("acme", 1, nil)
48		s.Rollback("acme", 2, 1)
49		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
50	
51		recs, cp, err := s.AuditExport("acme", 0)
52		if err != nil {
53			t.Fatal(err)
54		}
55	
56		got, err := RecheckDecisionOffline("acme", recs, cp, 2)
57		if err != nil {
58			t.Fatalf("offline review: %v", err)
59		}
60		if !got.Consistent {
61			t.Fatalf("review inconsistent: original=%+v recomputed=%+v", got.Original, got.Recomputed)
62		}
63		if !reflect.DeepEqual(got.Original, original) {
64			t.Fatalf("original = %+v, want %+v", got.Original, original)
65		}
66		if !reflect.DeepEqual(got.Recomputed, original) || got.Recomputed.Version != v1 {
67			t.Fatalf("recomputed = %+v, want %+v", got.Recomputed, original)
68		}
69		if got.Seq != 2 {
70			t.Fatalf("seq = %d, want 2", got.Seq)
71		}
72	
73		denied, err := RecheckDecisionOffline("acme", recs, cp, 3)
74		if err != nil {
75			t.Fatalf("offline review deny: %v", err)
76		}
77		if !denied.Consistent || !reflect.DeepEqual(denied.Original, origDeny) {
78			t.Fatalf("deny review = %+v, want consistent with %+v", denied, origDeny)
79		}
80		if denied.Recomputed.Allowed || denied.Recomputed.Reason != "no matching allow policy" {
81			t.Fatalf("recomputed deny = %+v", denied.Recomputed)
82		}
83	}
84	
85	func TestOfflineReviewUsesRollbackRecordContentAndNewVersion(t *testing.T) {
86		s := NewStore()
87		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)}) // v1 seq1
88		s.Publish("acme", 1, nil)                                                       // v2 seq2
89		v3, err := s.Rollback("acme", 2, 1)                                             // v3 seq3, carries v1 content
90		if err != nil {
91			t.Fatal(err)
92		}
93		original := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")) // seq4, version 3
94		if !original.Allowed || original.Version != 3 {
95			t.Fatalf("setup decision = %+v", original)
96		}
97		recs, cp, err := s.AuditExport("acme", 0)
98		if err != nil {
99			t.Fatal(err)
100		}
101		got, err := RecheckDecisionOffline("acme", recs, cp, 4)
102		if err != nil {
103			t.Fatalf("offline review: %v", err)
104		}
105		if !got.Consistent {
106			t.Fatalf("rollback review inconsistent: %+v vs %+v", got.Original, got.Recomputed)
107		}
108		if got.Recomputed.Version != v3 || !got.Recomputed.Allowed {
109			t.Fatalf("recomputed must use rollback's new version %d: %+v", v3, got.Recomputed)
110		}
111		if !reflect.DeepEqual(got.Recomputed.Matched, []string{"p1"}) {
112			t.Fatalf("recomputed matched = %v, want [p1]", got.Recomputed.Matched)
113		}
114	}
115	
116	func TestOfflineReviewVersionZeroCases(t *testing.T) {
117		s := NewStore()
118		// A legal request before any publish: not-yet-published denial, version 0.
119		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")) // seq1
120		// Envelope rejections are recorded too.
121		missing := request("acme", "u1", "r1", "org/a", "read")
122		missing.Action = ""
123		s.Decide("acme", missing) // seq2
124		mismatch := request("acme", "u1", "r1", "org/a", "read")
125		mismatch.SubjectOrg = "globex"
126		s.Decide("acme", mismatch) // seq3
127		badScope := request("acme", "u1", "r1", "org/../a", "read")
128		s.Decide("acme", badScope) // seq4
129		disabled := request("acme", "u1", "r1", "org/a", "read")
130		disabled.Subject.Disabled = true
131		s.Decide("acme", disabled) // seq5
132	
133		recs, cp, err := s.AuditExport("acme", 0)
134		if err != nil {
135			t.Fatal(err)
136		}
137		wantReasons := []string{
138			"organization has no published version",
139			"missing action",
140			"organization mismatch",
141			"invalid scope: scope \"org/../a\" contains invalid segment \"..\"",
142			"subject is disabled",
143		}
144		for seq, reason := range wantReasons {
145			got, err := RecheckDecisionOffline("acme", recs, cp, seq+1)
146			if err != nil {
147				t.Fatalf("seq %d: %v", seq+1, err)
148			}
149			if !got.Consistent {
150				t.Fatalf("seq %d inconsistent: %+v vs %+v", seq+1, got.Original, got.Recomputed)
151			}
152			if got.Original.Version != 0 || got.Recomputed.Version != 0 {
153				t.Fatalf("seq %d versions = %d/%d, want 0", seq+1, got.Original.Version, got.Recomputed.Version)
154			}
155			if got.Original.Allowed || got.Recomputed.Allowed || got.Recomputed.Reason != reason {
156				t.Fatalf("seq %d recomputed = %+v, want denial %q", seq+1, got.Recomputed, reason)
157			}
158		}
