581	// TestOfflineReviewEnforcesRequestRulesAtNonZeroVersion proves the audit
582	// fingerprint cannot substitute for evaluating the request: a record that
583	// names an existing non-zero version with a matching allow policy must
584	// still recompute to the same envelope denial the online decision gives.
585	func TestOfflineReviewEnforcesRequestRulesAtNonZeroVersion(t *testing.T) {
586		const org = "acme"
587		for name, tc := range offlineBadRequestCases(org) {
588			t.Run(name, func(t *testing.T) {
589				req := tc.modify(request(org, "u1", "r1", "org/a", "read"))
590				recs, cp := offlineForgedAllowChain(t, org, req, "")
591				got, err := RecheckDecisionOffline(org, recs, cp, 2)
592				if err != nil {
593					t.Fatalf("request denial is a result, not an error: %v", err)
594				}
595				if got.Consistent {
596					t.Fatalf("original allow must not match the recomputed denial: %+v", got)
597				}
598				if !got.Original.Allowed || got.Original.Version != 1 {
599					t.Fatalf("original claim not preserved: %+v", got.Original)
600				}
601				if got.Recomputed.Allowed || got.Recomputed.Reason != tc.reason {
602					t.Fatalf("recomputed = %+v, want denial %q", got.Recomputed, tc.reason)
603				}
604				if got.Recomputed.Version != 0 {
605					t.Fatalf("envelope rejection used no version, got %d", got.Recomputed.Version)
606				}
607				if len(got.Recomputed.Matched) != 0 {
608					t.Fatalf("envelope rejection matched no policies, got %v", got.Recomputed.Matched)
609				}
610			})
611		}
612	
613		t.Run("invalid scope forms", func(t *testing.T) {
614			for name, scope := range invalidScopeReviews() {
615				t.Run(name, func(t *testing.T) {
616					req := request(org, "u1", "r1", scope, "read")
617					recs, cp := offlineForgedAllowChain(t, org, req, "")
618					got, err := RecheckDecisionOffline(org, recs, cp, 2)
619					if err != nil {
620						t.Fatalf("invalid scope is a result, not an error: %v", err)
621					}
622					if got.Consistent || got.Recomputed.Allowed ||
623						got.Recomputed.Version != 0 || len(got.Recomputed.Matched) != 0 {
624						t.Fatalf("invalid scope %q review = %+v", scope, got)
625					}
626					if want := "invalid scope: "; got.Recomputed.Reason == want ||
627						len(got.Recomputed.Reason) <= len(want) ||
628						got.Recomputed.Reason[:len(want)] != want {
629						t.Fatalf("reason = %q, want an invalid-scope denial", got.Recomputed.Reason)
630					}
631				})
632			}
