240	// TestInvalidBytesFingerprintBuildsChainOfMixedRecords checks ordinary
241	// and invalid-byte records chaining together: ordinary records keep the
242	// legacy JSON fingerprint, the invalid-byte record verifies and is pinned
243	// by the checkpoint, and tampering either family fails with
244	// ErrInvalidRange.
245	func TestInvalidBytesFingerprintBuildsChainOfMixedRecords(t *testing.T) {
246		s := NewStore()
247		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
248		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
249		s.Publish("acme", 1, []Policy{{
250			ID:      "策" + invalidByte + "略",
251			Subject: "用" + invalidByte + "戶",
252			Action:  "read",
253			Scope:   "org/a",
254			Effect:  EffectAllow,
255		}})
256		recs, cp, err := s.AuditExport("acme", 0)
257		if err != nil {
258			t.Fatal(err)
259		}
260		if err := VerifyAudit("acme", recs, cp); err != nil {
261			t.Fatalf("mixed chain: %v", err)
262		}
263		if got := fingerprintFor(&recs[0]); got != legacyJSONFingerprint(&recs[0]) {
264			t.Fatal("valid-UTF-8 record changed fingerprint family")
265		}
266		if got := fingerprintFor(&recs[1]); got != legacyJSONFingerprint(&recs[1]) {
267			t.Fatal("valid-UTF-8 decision changed fingerprint family")
268		}
269		if got := fingerprintFor(&recs[2]); got == legacyJSONFingerprint(&recs[2]) {
270			t.Fatal("invalid-byte record still uses the JSON fingerprint")
271		}
272		if recs[2].Fingerprint != cp.Fingerprint {
273			t.Fatal("checkpoint does not pin the raw-encoded final record")
274		}
275		bad := cloneExportedRecords(recs)
276		bad[2].Change.Policies[0].ID = strings.Replace(bad[2].Change.Policies[0].ID, invalidByte, anotherInvalidByte, 1)
277		if err := VerifyAudit("acme", bad, cp); !errors.Is(err, ErrInvalidRange) {
278			t.Fatalf("tampered invalid-byte record err = %v, want ErrInvalidRange", err)
279		}
280		bad = cloneExportedRecords(recs)
281		bad[0].Change.Policies[0].ID = "p2"
282		if err := VerifyAudit("acme", bad, cp); !errors.Is(err, ErrInvalidRange) {
283			t.Fatalf("tampered ordinary record err = %v, want ErrInvalidRange", err)
284		}
285	}
